var qualifiedAssets={queryUserFinOrInvest:qualified.queryUserFinOrInvestMethod(),initPage:function(){qualified.tabChange(".tab li",".improveText","cur");$("#upLoadFinancialBtn").click(function(){$("#financialNameRead").text()==""?DJ.dialog.error("请选择文件后再上传"):qualified.ajaxSubmit("financialCertificate","financialPro","financialNameRead","financialFileUpload","qualifiedAssets")});$("#financialFileUpload").unbind().change(function(){qualified.judgeFile(this.files[0].name)=="other"?DJ.dialog.error("文件格式不符合要求"):qualified.fileSizeJudge(this,"financialNameRead","financiList")})},queryFileList:function(){var n=this;$.ajax({url:"/AppService/business/queryFileUploadRecord.xhtml",type:"POST",dataType:"json",async:!1,success:function(t){var i,r;t.returnCode=="0000"&&(t.data.length>0&&(i=qualified.dataReorganization(t.data),i.financialCertificate.length>0?(r=i.financialCertificate,n.renderUploadEL(r,"#financiList","financialCertificate"),$(".hasFile").show(),$(".noneFile").hide()):($(".hasFile").hide(),$(".noneFile").show())),n.maskDisable())}})},financialUpFile:function(){$("#financialFileUpload").click()},renderUploadEL:function(n,t,i){var r=this;$(t).html("").append(n.map(function(n){var t=qualified.judgeFile(n.filename);return fileEl=t=="image"?'<li class="image" data-type="image"><em><\/em><b data-key='+n.key+" onclick=\"qualified.queryCurrentFile(this,'image')\">"+n.filename+"<\/b><i onclick=\"qualified.deleteCurrentFile('"+n.recordId+"','3','"+n.key+"','"+i+"')\"><\/i><\/li>":t=="pdf"?'<li class="pdf" data-type="pdf"><em><\/em><b data-key='+n.key+" onclick=\"qualified.queryCurrentFile(this,'pdf')\">"+n.filename+"<\/b><i onclick=\"qualified.deleteCurrentFile('"+n.recordId+"','3','"+n.key+"','"+i+"')\"><\/i><\/li>":t=="viedo"?'<li class="viedo"  data-type="viedo"><em><\/em><b data-key='+n.key+" onclick=\"qualified.queryCurrentFile(this,'viedo')\">"+n.filename+"<\/b><i onclick=\"qualified.deleteCurrentFile('"+n.recordId+"','3','"+n.key+"','"+i+"')\"><\/i><\/li>":""}).join(""))},maskDisable:function(){this.queryUserFinOrInvest.financialCertificate?($("#financialMask").show(),$("#financialMask").siblings(".proUpload").hide()):this.queryUserFinOrInvest.financialCertificate||($("#financialMask").hide(),$("#financialMask").siblings(".proUpload").show())}};qualifiedAssets.initPage();qualifiedAssets.queryFileList()